import requirements from '../../../fixtures/m01-requirements.json';
import observed from '../../../fixtures/m01-observed.json';
import { selectors, approved, expectedPage, emptyGuest } from '../../../support/m01';

describe('M01 supplied-policy navigation (prerequisites fail explicitly)', () => {
  it('N08-TC01 — approved product Next destination', () => {
    const rule = approved(requirements.productNext, 'N08-TC01', 'productNext');
    cy.visit(observed.product);
    cy.get(selectors.stage).find(selectors.next).click();
    expectedPage(rule.expected);
  });
  it('N08-TC02 — approved sequence-specific Previous and direct-entry fallback', () => {
    const rule = approved(requirements.cartPrevious, 'N08-TC02', 'cartPrevious');
    expect(rule.sequences, 'direct and product-to-cart sequences').to.have.length(2);
    expect(rule.sequences.map(sequence => sequence.entry).sort())
      .deep.eq(['direct', 'product-next']);
    rule.sequences.forEach(sequence => {
      expect(sequence.entry).to.be.oneOf(['direct', 'product-next']);
      if (sequence.entry === 'product-next') {
        const productRule = approved(requirements.productNext, 'N08-TC02', 'productNext');
        expect(productRule.expected.pathname,
          'N08-TC02: product-next sequence requires an approved route to cart').eq('/cart');
        cy.visit(observed.product);
        cy.get(selectors.stage).find(selectors.next).click();
        cy.location('pathname').should('eq', '/cart');
      } else {
        emptyGuest();
      }
      cy.get(selectors.stage).find(selectors.previous).click();
      expectedPage(sequence.expected);
      cy.clearCookies();
      cy.clearLocalStorage();
    });
  });
  it('N08-TC03 — approved empty guest Next policy', () => {
    const rule = approved(requirements.emptyGuestNext, 'N08-TC03', 'emptyGuestNext');
    emptyGuest();
    expect(rule.action, 'supplied policy mode').to.be.oneOf(['navigate', 'disabled']);
    if (rule.action === 'navigate') {
      cy.get(selectors.stage).find(selectors.next).click();
      expectedPage(rule.expected);
    } else {
      // Supplied selector must be grounded in separately recorded actual DOM.
      expect(rule.selectorEvidence).to.be.a('string').and.not.be.empty;
      cy.get(rule.disabledSelector).should('be.visible').and('be.disabled');
      cy.location('pathname').should('eq', '/cart');
    }
  });
});

describe('N08-TC04 — supplied synthetic role/cart rows; not server authorization', () => {
  ['guestPopulated', 'customerEmpty', 'customerPopulated'].forEach(key => {
    it('N08-TC04 — client UI simulation ' + key, () => {
      const row = approved(requirements.roleCart[key], 'N08-TC04', key);
      expect(row.syntheticOnly).eq(true);
      expect(row.fixtureEvidence, 'documented session/storage UI schema').to.be.a('string').and.not.be.empty;
      expect(row.storage).to.be.an('object');
      expect(row.sessionBody).to.be.an('object').and.have.property('user');
      expect(row.cartMarker, 'inspected state marker').to.be.an('object');
      expect(row.roleMarker, 'inspected rendered role marker, not just stubbed response').to.be.an('object');
      expect(row.action).to.be.oneOf(['navigate', 'disabled']);
      cy.intercept('GET', '/api/v1/auth/session', { statusCode: 200, body: row.sessionBody }).as('syntheticSession');
      cy.visit('/cart', {
        onBeforeLoad(win) {
          win.localStorage.clear();
          Object.entries(row.storage).forEach(([name, value]) => {
            if (typeof value !== 'string') throw new Error('N08-TC04 storage values must be serialized strings');
            win.localStorage.setItem(name, value);
          });
        }
      });
      cy.wait('@syntheticSession').its('response.body').should('deep.eq', row.sessionBody);
      cy.get(row.cartMarker.selector).should('be.visible').and('have.text', row.cartMarker.text);
      cy.get(row.roleMarker.selector).should('be.visible').and('have.text', row.roleMarker.text);
      if (row.action === 'navigate') {
        cy.get(selectors.stage).find(selectors.next).click();
        expectedPage(row.expected);
      } else {
        expect(row.selectorEvidence).to.be.a('string').and.not.be.empty;
        cy.get(row.disabledSelector).should('be.visible').and('be.disabled');
        cy.location('pathname').should('eq', '/cart');
      }
    });
  });
});

